$tempRoot = '/export/user\AppData\Local\Temp\ji-reaccept-pi-phase0-54c855a'
$tempParent = '/export/user\AppData\Local\Temp'
New-Item -ItemType Directory -LiteralPath $tempRoot | Out-Null
$resolvedTemp = (Resolve-Path -LiteralPath $tempRoot).Path
$resolvedParent = (Resolve-Path -LiteralPath $tempParent).Path
if ($resolvedTemp -ne $tempRoot -or (Split-Path -Parent $resolvedTemp) -ne $resolvedParent) { throw 'unsafe temp path' }
$archive = Join-Path $tempRoot 'pi.tar'
$source = Join-Path $tempRoot 'source'
$generated = Join-Path $tempRoot 'generated'
git -C original-pi archive --format=tar -o $archive 6c87d9a026677b601e8278030dcf1ad97fe0bd86
if ($LASTEXITCODE -ne 0) { throw 'git archive failed' }
New-Item -ItemType Directory -LiteralPath $source | Out-Null
tar -xf $archive -C $source
if ($LASTEXITCODE -ne 0) { throw 'tar extract failed' }
Push-Location $source
try {
  & npm.cmd ci --ignore-scripts *> $null
  if ($LASTEXITCODE -ne 0) { throw 'npm ci failed' }
  & npm.cmd run build --workspace=@earendil-works/pi-telemetry *> $null
  if ($LASTEXITCODE -ne 0) { throw 'telemetry build failed' }
  & npm.cmd run hydrate-model-data --workspace=@earendil-works/pi-ai *> $null
  if ($LASTEXITCODE -ne 0) { throw 'model hydration failed' }
  & npm.cmd run build:offline --workspace=@earendil-works/pi-ai *> $null
  if ($LASTEXITCODE -ne 0) { throw 'ai build failed' }
  & npm.cmd run build --workspace=@earendil-works/pi-agent-core *> $null
  if ($LASTEXITCODE -ne 0) { throw 'agent build failed' }
  & npm.cmd run build --workspace=@earendil-works/pi-protocol *> $null
  if ($LASTEXITCODE -ne 0) { throw 'protocol build failed' }
  Copy-Item -LiteralPath 'E:\Projects\Code\AI\Ji\scripts\extract-pi-fixtures.mjs' -Destination (Join-Path $source '.ji-extract-pi-fixtures.mjs')
  & node (Join-Path $source '.ji-extract-pi-fixtures.mjs') $generated *> $null
  if ($LASTEXITCODE -ne 0) { throw 'fixture extraction failed' }
} finally {
  Pop-Location
}
$names = @('provider-faux-stream.json','agent-loop-tool-run.json','session-tool-run-log.json','compaction-prepare.json','protocol-client-hello.json')
$mismatches = 0
foreach ($name in $names) {
  $actual = (Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $generated $name)).Hash
  $expected = (Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path 'E:\Projects\Code\AI\Ji\contracts\fixtures\pi-6c87d9a' $name)).Hash
  if ($actual -ne $expected) { $mismatches++ }
}
'PI_PUBLIC_API_REGENERATED=5'
'PI_RAW_BYTE_MISMATCHES=' + $mismatches

